//! Golden differential tests against the Go implementation (fixtures generated by
//! `go run -mod=vendor ./hack/golden/metallb crates/ctrl-metallb/tests/fixtures`).
//!
//! Each scenario runs [`MetalLBManager`] / [`CleanupHandler`] against `ctrlrt-fake` with the
//! same inputs as the Go program and compares, byte for byte: every step's result, error
//! string and events, and the `encoding/json` bytes of the IPAddressPool, L2Advertisement and
//! DPFHCPProvisioner (stored copy and the caller's in-memory copy).
//!
//! Normalization (also applied by the Go generator): condition `lastTransitionTime`
//! (`metav1.Now()`) is set to `2025-01-01T00:00:00Z`. Go's "CRD not installed" case uses an
//! interceptor returning `*meta.NoKindMatchError`; here `with_unserved` does the same.

use std::collections::BTreeMap;
use std::sync::Arc;

use apis::hypershift::v1beta1 as hyperv1;
use apis::metallb::v1beta1 as metallbv1beta1;
use apis::provisioning::v1alpha1 as provisioningv1alpha1;
use common::OperatorConfig;
use ctrl_metallb::{CleanupHandler, MetalLBManager};
use ctrlrt::{Client, Ctx, FakeRecorder, ObjectKey, ReconcileResult};
use ctrlrt_fake::{FakeClientBuilder, InitObject, Scheme};
use k8s_openapi::apimachinery::pkg::apis::meta::v1::{ObjectMeta, Time};
use serde::Deserialize;

#[derive(Debug, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase")]
struct Step {
    requeue: bool,
    requeue_after: i64,
    error: String,
    events: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    steps: Vec<Step>,
    objects: BTreeMap<String, String>,
}

fn fixture(name: &str) -> Fixture {
    let path = format!("{}/tests/fixtures/{name}.json", env!("CARGO_MANIFEST_DIR"));
    let s = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{path}: {e}"));
    serde_json::from_str(&s).unwrap()
}

fn scheme() -> Scheme {
    Scheme::new()
        .register::<provisioningv1alpha1::DPFHCPProvisioner>()
        .register::<provisioningv1alpha1::DPFHCPProvisionerConfig>()
        .register::<metallbv1beta1::IPAddressPool>()
        .register::<metallbv1beta1::L2Advertisement>()
        .register::<hyperv1::HostedCluster>()
        .register::<hyperv1::NodePool>()
}

fn provisioner(policy: &str, vip: &str) -> provisioningv1alpha1::DPFHCPProvisioner {
    provisioningv1alpha1::DPFHCPProvisioner {
        metadata: ObjectMeta {
            name: Some("test-provisioner".into()),
            namespace: Some("test-ns".into()),
            generation: Some(3),
            uid: Some("uid-1".into()),
            ..Default::default()
        },
        spec: provisioningv1alpha1::DPFHCPProvisionerSpec {
            control_plane_availability_policy: policy.into(),
            virtual_ip: vip.into(),
            ..Default::default()
        },
        ..Default::default()
    }
}

fn owner_labels() -> BTreeMap<String, String> {
    BTreeMap::from([
        (
            common::LABEL_DPFHCP_PROVISIONER_NAME.to_string(),
            "test-provisioner".to_string(),
        ),
        (
            common::LABEL_DPFHCP_PROVISIONER_NAMESPACE.to_string(),
            "test-ns".to_string(),
        ),
    ])
}

fn drifted_pool() -> metallbv1beta1::IPAddressPool {
    let mut labels = owner_labels();
    labels.insert("extra".into(), "kept".into());
    metallbv1beta1::IPAddressPool {
        metadata: ObjectMeta {
            name: Some("test-provisioner".into()),
            namespace: Some(common::OPENSHIFT_OPERATORS_NAMESPACE.into()),
            labels: Some(labels),
            annotations: Some(BTreeMap::from([("note".into(), "user".into())])),
            ..Default::default()
        },
        spec: metallbv1beta1::IPAddressPoolSpec {
            addresses: Some(vec!["192.168.1.200/32".into(), "10.0.0.0/24".into()]),
            avoid_buggy_ips: true,
            service_allocation: Some(metallbv1beta1::ServiceAllocation {
                priority: 5,
                namespaces: vec!["clusters-test-provisioner".into()],
                ..Default::default()
            }),
            auto_assign: Some(false),
            ..Default::default()
        },
        ..Default::default()
    }
}

fn drifted_advert() -> metallbv1beta1::L2Advertisement {
    metallbv1beta1::L2Advertisement {
        metadata: ObjectMeta {
            name: Some("advertise-test-provisioner".into()),
            namespace: Some(common::OPENSHIFT_OPERATORS_NAMESPACE.into()),
            labels: Some(owner_labels()),
            ..Default::default()
        },
        spec: metallbv1beta1::L2AdvertisementSpec {
            ip_address_pools: vec!["wrong-pool".into()],
            interfaces: vec!["eth0".into()],
            ..Default::default()
        },
        ..Default::default()
    }
}

fn unowned_pool() -> metallbv1beta1::IPAddressPool {
    let mut p = drifted_pool();
    p.metadata.labels = Some(BTreeMap::from([("other".into(), "owner".into())]));
    p
}

fn unowned_advert() -> metallbv1beta1::L2Advertisement {
    let mut a = drifted_advert();
    a.metadata.labels = None;
    a
}

fn step(res: ctrlrt::Result<ReconcileResult>, rec: &FakeRecorder) -> Step {
    let (r, error) = match res {
        Ok(r) => (r, String::new()),
        Err(e) => (ReconcileResult::default(), e.to_string()),
    };
    Step {
        requeue: r.requeue,
        requeue_after: r.requeue_after.as_nanos() as i64,
        error,
        events: rec.drain(),
    }
}

fn normalize(p: &mut provisioningv1alpha1::DPFHCPProvisioner) {
    let fixed: k8s_openapi::jiff::Timestamp = "2025-01-01T00:00:00Z".parse().unwrap();
    for c in &mut p.status.conditions {
        c.last_transition_time = Time(fixed);
    }
}

async fn dump(
    c: &Client,
    p: &mut provisioningv1alpha1::DPFHCPProvisioner,
) -> BTreeMap<String, String> {
    let mut out = BTreeMap::new();
    normalize(p);
    out.insert(
        "provisioner.memory".into(),
        serde_json::to_string(p).unwrap(),
    );
    let stored = c
        .get::<provisioningv1alpha1::DPFHCPProvisioner>(&ObjectKey::new(
            "test-ns",
            "test-provisioner",
        ))
        .await
        .ok()
        .map(|mut s| {
            normalize(&mut s);
            serde_json::to_string(&s).unwrap()
        });
    out.insert("provisioner.stored".into(), stored.unwrap_or_default());
    let pool = c
        .get::<metallbv1beta1::IPAddressPool>(&ObjectKey::new(
            common::OPENSHIFT_OPERATORS_NAMESPACE,
            "test-provisioner",
        ))
        .await
        .ok()
        .map(|o| serde_json::to_string(&o).unwrap());
    out.insert("ipaddresspool".into(), pool.unwrap_or_default());
    let advert = c
        .get::<metallbv1beta1::L2Advertisement>(&ObjectKey::new(
            common::OPENSHIFT_OPERATORS_NAMESPACE,
            "advertise-test-provisioner",
        ))
        .await
        .ok()
        .map(|o| serde_json::to_string(&o).unwrap());
    out.insert("l2advertisement".into(), advert.unwrap_or_default());
    out
}

#[derive(Clone, Copy, PartialEq)]
enum NoMatch {
    None,
    Pool,
    Advert,
}

fn build(objs: Vec<InitObject>, status: bool, no_match: NoMatch) -> Client {
    let mut b = FakeClientBuilder::new()
        .with_scheme(scheme())
        .with_objects(objs);
    if status {
        b = b.with_status_subresource::<provisioningv1alpha1::DPFHCPProvisioner>();
    }
    match no_match {
        NoMatch::None => {}
        NoMatch::Pool => b = b.with_unserved::<metallbv1beta1::IPAddressPool>(),
        NoMatch::Advert => b = b.with_unserved::<metallbv1beta1::L2Advertisement>(),
    }
    b.build()
}

fn compare(name: &str, got_steps: Vec<Step>, got_objects: BTreeMap<String, String>) {
    let want = fixture(name);
    assert_eq!(got_steps, want.steps, "{name}: steps differ from Go");
    assert_eq!(
        got_objects.keys().collect::<Vec<_>>(),
        want.objects.keys().collect::<Vec<_>>(),
        "{name}: object set"
    );
    for (k, w) in &want.objects {
        assert_eq!(&got_objects[k], w, "{name}: {k} differs from Go");
    }
}

async fn run_configure(
    name: &str,
    mut p: provisioningv1alpha1::DPFHCPProvisioner,
    objs: Vec<InitObject>,
    disabled: bool,
    no_match: NoMatch,
    runs: usize,
) {
    let ctx = Ctx::background();
    let mut all = vec![ctrlrt_fake::obj_mut(&mut p)];
    all.extend(objs);
    let c = build(all, true, no_match);
    let rec = Arc::new(FakeRecorder::new(100));
    let m = MetalLBManager::new(c.clone(), rec.clone());
    let cfg = OperatorConfig {
        disable_metal_lb: disabled,
        ..Default::default()
    };
    let mut steps = Vec::new();
    for _ in 0..runs {
        let res = m.configure_metal_lb(&ctx, &mut p, &cfg).await;
        steps.push(step(res, &rec));
    }
    let objects = dump(&c, &mut p).await;
    compare(name, steps, objects);
}

async fn run_cleanup(name: &str, objs: Vec<InitObject>, no_match: NoMatch, runs: usize) {
    let ctx = Ctx::background();
    let mut p = provisioner(hyperv1::HIGHLY_AVAILABLE, "192.168.1.100");
    let mut all = vec![ctrlrt_fake::obj_mut(&mut p)];
    all.extend(objs);
    let c = build(all, false, no_match);
    let rec = Arc::new(FakeRecorder::new(100));
    let h = CleanupHandler::new(c.clone(), rec.clone());
    let mut steps = Vec::new();
    for _ in 0..runs {
        let res = h.cleanup(&ctx, &p).await;
        steps.push(step(res, &rec));
    }
    let objects = dump(&c, &mut p).await;
    compare(name, steps, objects);
}

